// Package icons provides file and folder icons for the side bar: the icon
// set of the "File & Folder Icons" VS Code extension (nextbook, MIT), which
// draws glyphs from five icon fonts (file-icons, Font Awesome, Octicons,
// Mfizz and Devicons). See LICENSES.md.
//
// The fonts are subsets of the extension's fonts (only the glyphs the theme
// uses), converted to TrueType; theme.json is a compact copy of its icon
// theme. Both are regenerated by scripts/convert-icons.py.
package icons

import (
	"embed"
	"encoding/json"
	"image/color"
	"path"
	"strconv"
	"strings"
	"sync"

	"gioui.org/font"
	"gioui.org/font/opentype"
)

//go:embed fonts/*.ttf theme.json
var files embed.FS

// Icon is one glyph in one of the icon fonts.
type Icon struct {
	Font  font.Font
	Rune  rune
	Color color.NRGBA // zero: use the text color
}

type section struct {
	File                string            `json:"file"`
	Folder              string            `json:"folder"`
	FolderExpanded      string            `json:"folderExpanded"`
	FileExtensions      map[string]string `json:"fileExtensions"`
	FileNames           map[string]string `json:"fileNames"`
	FolderNames         map[string]string `json:"folderNames"`
	FolderNamesExpanded map[string]string `json:"folderNamesExpanded"`
}

type theme struct {
	Fonts []string                      `json:"fonts"`
	Defs  map[string][3]json.RawMessage `json:"defs"` // [font index, code point, color]
	Dark  section                       `json:"dark"`
	Light section                       `json:"light"`
}

type def struct {
	font  int
	r     rune
	color color.NRGBA
}

var (
	once  sync.Once
	th    *theme
	defs  map[string]def
	faces []font.FontFace
)

func load() {
	data, err := files.ReadFile("theme.json")
	if err != nil {
		return
	}
	var t theme
	if json.Unmarshal(data, &t) != nil {
		return
	}
	defs = make(map[string]def, len(t.Defs))
	for k, v := range t.Defs {
		var fi, cp int
		var col string
		_ = json.Unmarshal(v[0], &fi)
		_ = json.Unmarshal(v[1], &cp)
		_ = json.Unmarshal(v[2], &col)
		defs[k] = def{font: fi, r: rune(cp), color: hex(col)}
	}
	for _, name := range t.Fonts {
		b, err := files.ReadFile("fonts/" + name + ".ttf")
		if err != nil {
			continue
		}
		face, err := opentype.Parse(b)
		if err != nil {
			continue
		}
		faces = append(faces, font.FontFace{Font: font.Font{Typeface: typeface(name)}, Face: face})
	}
	th = &t
}

func typeface(name string) font.Typeface { return font.Typeface("inks-" + name) }

func hex(s string) color.NRGBA {
	s = strings.TrimPrefix(s, "#")
	if len(s) != 6 {
		return color.NRGBA{}
	}
	v, err := strconv.ParseUint(s, 16, 32)
	if err != nil {
		return color.NRGBA{}
	}
	return color.NRGBA{uint8(v >> 16), uint8(v >> 8), uint8(v), 255}
}

// Faces returns the icon fonts, to add to a text shaper's collection.
func Faces() []font.FontFace {
	once.Do(load)
	return faces
}

// For returns the icon for a file or folder name. light picks colors meant
// for light backgrounds.
func For(name string, dir, expanded, light bool) (Icon, bool) {
	once.Do(load)
	if th == nil {
		return Icon{}, false
	}
	s := &th.Dark
	if light {
		s = &th.Light
	}
	lower := strings.ToLower(name)
	key := ""
	switch {
	case dir && expanded:
		if key = s.FolderNamesExpanded[lower]; key == "" {
			key = s.FolderExpanded
		}
	case dir:
		if key = s.FolderNames[lower]; key == "" {
			key = s.Folder
		}
	default:
		key = fileKey(s, lower)
	}
	d, ok := defs[key]
	if !ok || d.font >= len(th.Fonts) {
		return Icon{}, false
	}
	return Icon{Font: font.Font{Typeface: typeface(th.Fonts[d.font])}, Rune: d.r, Color: d.color}, true
}

// fileKey matches the way VS Code applies icon themes: the full name, then
// the longest extension ("foo.test.js": "test.js", then "js").
func fileKey(s *section, lower string) string {
	if k := s.FileNames[lower]; k != "" {
		return k
	}
	base := path.Base(lower)
	for i := 0; i < len(base); i++ {
		if base[i] != '.' {
			continue
		}
		if k := s.FileExtensions[base[i+1:]]; k != "" {
			return k
		}
	}
	if strings.HasPrefix(base, ".") { // ".gitignore": also try "gitignore"
		if k := s.FileExtensions[base[1:]]; k != "" {
			return k
		}
	}
	return s.File
}
